"""## 6. Connect to Snowflake and RabbitMQ

The exchange name is the same `zomato_exchange` topic exchange used by the supplied Part D notebook. The FreshCart consumer uses its own queue and routing key `freshcart.order.created`, so the existing driver bindings are unaffected.
"""

import snowflake.connector

conn = snowflake_io.connect()
print("Connected to Snowflake:", conn is not None)

rabbit_params = pika.URLParameters(os.environ["AMQP_URL"])
rabbit_connection = pika.BlockingConnection(rabbit_params)
rabbit_channel = rabbit_connection.channel()
rabbit_channel.exchange_declare(exchange="zomato_exchange", exchange_type="topic", durable=True)

FRESHCART_ROUTING_KEY = "freshcart.order.created"
FRESHCART_QUEUE = "freshcart_lakehouse_consumer"
rabbit_channel.queue_declare(queue=FRESHCART_QUEUE, durable=True)
rabbit_channel.queue_bind(exchange="zomato_exchange", queue=FRESHCART_QUEUE, routing_key=FRESHCART_ROUTING_KEY)
print("RabbitMQ connected.")
print("Exchange:", "zomato_exchange")
print("Queue:", FRESHCART_QUEUE)
print("Binding:", FRESHCART_ROUTING_KEY)

