"""## 8. Collect RabbitMQ messages for one minute and write the raw landing file

The consumer uses manual acknowledgements. It receives messages without acknowledging them immediately, validates the Part B web-order fields, writes the records with the original `extract.write_landing()`, and ACKs only after the landing file is successfully written. Invalid messages are rejected with `NACK(requeue=False)`.
"""

import uuid
from datetime import date

BATCH_ID = "rabbitmq_" + uuid.uuid4().hex[:12]
RUN_DATE = date(2026, 11, 14)
COLLECTION_SECONDS = 60

required_order_fields = {
    "order_id", "cust_email", "cust_name", "order_date",
    "amount", "currency", "pincode", "updated_at"
}
received_orders = []
delivery_tags = []
invalid_count = 0
deadline = time.monotonic() + COLLECTION_SECONDS
rabbit_channel.basic_qos(prefetch_count=500)

print(f"Collecting FreshCart messages for {COLLECTION_SECONDS} seconds...")
while time.monotonic() < deadline:
    method, properties, body = rabbit_channel.basic_get(queue=FRESHCART_QUEUE, auto_ack=False)
    if method is None:
        time.sleep(0.25)
        continue
    try:
        message = json.loads(body.decode("utf-8"))
        missing_fields = required_order_fields - set(message.keys())
        if missing_fields:
            raise ValueError(f"Missing fields: {sorted(missing_fields)}")
        received_orders.append(message)
        delivery_tags.append(method.delivery_tag)
    except Exception as exc:
        invalid_count += 1
        rabbit_channel.basic_nack(delivery_tag=method.delivery_tag, requeue=False)
        print("Rejected invalid message:", exc)

if not received_orders:
    raise RuntimeError("No valid FreshCart orders arrived in 60 seconds. Run the test publisher cell, then run this consumer cell again.")

landing_file = extract.write_landing(
    source="web", records=received_orders, run_id=BATCH_ID, run_date=RUN_DATE
)
if landing_file is None or not Path(landing_file).exists():
    raise RuntimeError("Landing file was not created; messages have not been ACKed.")

for tag in delivery_tags:
    rabbit_channel.basic_ack(delivery_tag=tag)

print("\nOne-minute collection complete.")
print("Valid messages:", len(received_orders))
print("Invalid messages rejected:", invalid_count)
print("Landing file:", landing_file)
print("ACK sent after landing file was written.")

"""## 9. Load the landing file into Bronze using the existing Part B `load_file()`

The target is `BRONZE.ORDERS_RAW`, exactly as in Part B. The same `BATCH_ID` and stage directory are reused for the replay test.
"""

STREAM_STAGE_DIR = f"stream_orders/{RUN_DATE.isoformat()}/{BATCH_ID}"

loaded_first_time = snowflake_io.load_file(
    conn=conn,
    local_path=landing_file,
    table="bronze.orders_raw",
    stage_dir=STREAM_STAGE_DIR
)
print("Rows loaded into BRONZE.ORDERS_RAW:", loaded_first_time)
assert loaded_first_time == len(received_orders), f"Expected {len(received_orders)} rows to load, got {loaded_first_time}"

"""## 10. Run the existing Part B transformations: Bronze → Silver → Gold

The SQL files execute in the same order as `run_pipeline.py`. The baseline run in Step 5 already populated CRM, FX and pincode source/reference data; this step rebuilds the transformations after the streamed orders arrive.
"""

def run_stream_transformations(conn, run_id, run_date):
    variables = {"run_id": run_id, "run_date": run_date.isoformat()}
    sql_dir = PROJECT_DIR / "sql"
    snowflake_io.run_sql_file(conn, sql_dir / "10_silver_orders_clean.sql", variables)
    snowflake_io.run_sql_file(conn, sql_dir / "20_silver_orders_dedup.sql", variables)
    snowflake_io.run_sql_file(conn, sql_dir / "30_dim_customers_scd2.sql", variables)
    snowflake_io.run_sql_file(conn, sql_dir / "31_ref_fx_daily.sql", variables)
    snowflake_io.run_sql_file(conn, sql_dir / "32_ref_pincode_geo.sql", variables)
    snowflake_io.run_sql_file(conn, sql_dir / "40_gold_fct_orders.sql", variables)

def get_gold_totals(conn):
    return snowflake_io.query_one(
        conn,
        """
        SELECT COUNT(*) AS total_orders,
               COALESCE(SUM(amount_inr), 0) AS total_revenue_inr,
               COALESCE(SUM(loyalty_points), 0) AS total_loyalty_points
        FROM gold.fct_orders
        """
    )

run_stream_transformations(conn, BATCH_ID, RUN_DATE)
gold_after_first_run = get_gold_totals(conn)
print("Gold totals after first streamed batch:")
print("Orders:", gold_after_first_run[0])
print("Revenue INR:", gold_after_first_run[1])
print("Loyalty points:", gold_after_first_run[2])

"""## 11. Verify the streamed order IDs reached Gold"""

streamed_order_ids = [order["order_id"] for order in received_orders]
placeholders = ", ".join(["%s"] * len(streamed_order_ids))
streamed_gold_rows = snowflake_io.query_all(
    conn,
    f"""
    SELECT order_id, amount_inr, loyalty_points, tier
    FROM gold.fct_orders
    WHERE order_id IN ({placeholders})
    ORDER BY order_id
    """,
    tuple(streamed_order_ids)
)
print("Streamed orders found in GOLD.FCT_ORDERS:")
for row in streamed_gold_rows:
    print(row)
assert len(streamed_gold_rows) == len(set(streamed_order_ids)), "Not every streamed order ID was found in Gold."

"""## 12. Replay the exact same batch a second time

Do **not** create a new landing file. Reuse the same `landing_file`, `BATCH_ID`, and `STREAM_STAGE_DIR`. Snowflake `COPY INTO` tracks files it has already loaded. The Part B Gold SQL uses a `MERGE` keyed by `order_id` and updates matched rows only when `row_hash` changes.
"""

loaded_second_time = snowflake_io.load_file(
    conn=conn,
    local_path=landing_file,
    table="bronze.orders_raw",
    stage_dir=STREAM_STAGE_DIR
)
print("Rows loaded on replay:", loaded_second_time)
assert loaded_second_time == 0, "The same staged file was loaded again. Check that the same file path and stage directory were reused."

run_stream_transformations(conn, BATCH_ID + "_replay", RUN_DATE)
gold_after_second_run = get_gold_totals(conn)
print("\nGold totals after replay:")
print("Orders:", gold_after_second_run[0])
print("Revenue INR:", gold_after_second_run[1])
print("Loyalty points:", gold_after_second_run[2])

"""## 13. Final idempotency verification"""

first = tuple(str(x) for x in gold_after_first_run)
second = tuple(str(x) for x in gold_after_second_run)
print("First run totals :", first)
print("Second run totals:", second)
assert first == second, "Idempotency check failed: Gold totals changed on replay."
print("\nSUCCESS: The same batch was replayed.")
print("Gold order count, revenue and loyalty points did not increase.")

"""## 14. Close connections"""

try:
    if rabbit_connection and rabbit_connection.is_open:
        rabbit_connection.close()
except Exception:
    pass
try:
    if conn:
        conn.close()
except Exception:
    pass
print("RabbitMQ and Snowflake connections closed.")

